"w": [
"",
"Inward rectifier K⁺ sets the resting potential.",
"L-type Ca²⁺ carries the nodal upstroke and the ventricular plateau.",
"T-type Ca²⁺ contributes to late phase 4 in nodal cells.",
"Cl⁻ channels do not carry phase 0."
],
